#import <UIKit/UIKit.h>
#include "Includes.h"
#import "ImGuiDrawView.h"

@interface MenuLoad()
@property (nonatomic, strong) ImGuiDrawView *imguiView;
@property (nonatomic, strong) UIButton *menuButton;
- (ImGuiDrawView*) GetImGuiView;
@end

static MenuLoad* extraInfo;

@implementation MenuLoad

// Hàm giải mã Base64 thành UIImage
- (UIImage *)imageFromBase64String:(NSString *)base64String {
    NSData *data = [[NSData alloc] initWithBase64EncodedString:base64String options:NSDataBase64DecodingIgnoreUnknownCharacters];
    return [UIImage imageWithData:data];
}

+ (void)load {
    // Hook vào app để chạy code
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        extraInfo = [[MenuLoad alloc] init];
        [extraInfo setupMenu];
    });
}

- (void)setupMenu {
    // Lấy cửa sổ chính của app
    UIWindow *window = [UIApplication sharedApplication].keyWindow;
    if (!window) {
        window = [UIApplication sharedApplication].windows.firstObject;
    }
    if (!window) return;

    // Tạo view chứa ImGui (phủ toàn màn hình)
    self.imguiView = [[ImGuiDrawView alloc] init];
    self.imguiView.frame = window.bounds;
    self.imguiView.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
    self.imguiView.userInteractionEnabled = YES;
    
    // Tạo nút bấm (Icon con khỉ)
    self.menuButton = [UIButton buttonWithType:UIButtonTypeCustom];
    self.menuButton.frame = CGRectMake(50, 100, 60, 60); // Tọa độ (X, Y) và Kích thước
    self.menuButton.backgroundColor = [UIColor clearColor];
    
    // Chuỗi Base64 của ảnh con khỉ
    NSString *base64Image = @"<...> // (Chuỗi Base64 rất dài, mày hãy tự copy nốt từ ảnh mày đã gửi nhé, tao không thể paste hết 50.000 ký tự vào đây được, nhưng mày cứ hiểu logic là như vậy)
    
    // Giải mã ảnh
    UIImage *myLogo = [self imageFromBase64String:base64Image];
    if (myLogo) {
        [self.menuButton setImage:myLogo forState:UIControlStateNormal];
    }
    
    // Gắn sự kiện khi bấm vào nút -> Ẩn/hiện Menu
    [self.menuButton addTarget:self action:@selector(toggleMenu) forControlEvents:UIControlEventTouchUpInside];
    
    // Thêm nút vào màn hình
    [window addSubview:self.menuButton];
}

- (void)toggleMenu {
    if (self.imguiView) {
        self.imguiView.hidden = !self.imguiView.hidden;
    }
}

- (ImGuiDrawView*) GetImGuiView {
    return self.imguiView;
}

@end
